def transform(grid):
    """Trace the colored markers' fixed L paths; intersections spawn a 4 diagonal."""
    out = [row[:] for row in grid]
    moves = {1: (-1, 2), 2: (0, -4), 3: (3, 0)}
    h, w = len(grid), len(grid[0]) if grid else 0
    paths = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color not in moves:
                continue
            dr, dc = moves[color]
            er, ec = r + dr, c + dc
            if not (0 <= er < h and 0 <= ec < w):
                continue
            cells = []
            rr, cc = r, c
            while cc != ec:
                cc += 1 if ec > cc else -1
                if (rr, cc) != (er, ec): cells.append((rr, cc))
            while rr != er:
                rr += 1 if er > rr else -1
                if (rr, cc) != (er, ec): cells.append((rr, cc))
            paths.append((color, (er, ec), cells))
    counts = {}
    for color, end, cells in paths:
        for cell in cells:
            counts[cell] = counts.get(cell, 0) + 1
    intersections = [cell for cell, n in counts.items() if n > 1]
    for color, end, cells in paths:
        for r, c in cells:
            if grid[r][c] == 0: out[r][c] = 5
        r, c = end
        if grid[r][c] == 0: out[r][c] = color
    for r, c in intersections:
        out[r][c] = 4
    for r, c in intersections:
        rr, cc = r + 1, c - 1
        while 0 <= rr < h and 0 <= cc < w:
            if grid[rr][cc] == 0: out[rr][cc] = 4
            rr += 1; cc -= 1
    return out
